<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?=e(csrf_token())?>"><title>Admin sign in</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="assets/css/style.css"></head><body class="login-shell"><div class="card login-card"><div class="card-body p-4 p-md-5"><a href="index.php" class="text-decoration-none fw-bold fs-4 text-dark">Pulse<span class="text-primary">Point</span></a><h2 class="fw-bold mt-4">Welcome back</h2><p class="text-secondary">Sign in to manage surveys and employee feedback.</p><div id="loginError" class="alert alert-danger d-none"></div><form id="loginForm"><div class="mb-3"><label class="form-label">Email</label><input type="email" class="form-control" name="email" value="admin@example.com" required></div><div class="mb-3"><label class="form-label">Password</label><input type="password" class="form-control" name="password" value="Admin@123" required></div><button class="btn btn-primary w-100 py-2" type="submit">Sign in</button></form><p class="small text-secondary mt-4 mb-0">Demo account: admin@example.com / Admin@123</p></div></div><script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="assets/js/app.js"></script><script>$('#loginForm').on('submit',function(e){e.preventDefault();$.ajax({url:'../api/auth.php',method:'POST',contentType:'application/json',data:JSON.stringify({action:'login',email:this.email.value,password:this.password.value,csrf_token:PulsePoint.csrf()})}).done(()=>location.href='dashboard.php').fail(x=>$('#loginError').removeClass('d-none').text(x.responseJSON?.message||'Login failed'))})</script></body></html>